#include <iostream>
#include <map>
#include <vector>
using namespace std;

const int MOD = 1000000007;

struct Number {
    int val;

    Number(long long v = 0) {
        if (v < 0) v %= MOD, v += MOD;
        if (v >= MOD) v %= MOD;
        val = v;
    }

    static int inverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return val; }

    Number& operator+=(const Number &other) {
        val += other.val;
        if (val >= MOD) val -= MOD;
        return *this;
    }

    Number& operator-=(const Number &other) {
        val -= other.val;
        if (val < 0) val += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
    #if !defined(_WIN32) || defined(_WIN64)
        return x % m;
    #endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    Number& operator*=(const Number &other) {
        val = fast_mod((uint64_t) val * other.val);
        return *this;
    }

    Number& operator/=(const Number &other) {
        return *this *= Number(inverse(other.val));
    }

    friend Number operator+(const Number &a, const Number &b) { return Number(a) += b; }
    friend Number operator-(const Number &a, const Number &b) { return Number(a) -= b; }
    friend Number operator*(const Number &a, const Number &b) { return Number(a) *= b; }
    friend Number operator/(const Number &a, const Number &b) { return Number(a) /= b; }

    Number& operator++() {
        val = val == MOD - 1 ? 0 : val + 1;
        return *this;
    }

    Number& operator--() {
        val = val == 0 ? MOD - 1 : val - 1;
        return *this;
    }

    Number operator++(int) { Number before = *this; ++*this; return before; }
    Number operator--(int) { Number before = *this; --*this; return before; }

    Number operator-() const {
        return val == 0 ? 0 : MOD - val;
    }

    bool operator==(const Number &other) const { return val == other.val; }
    bool operator!=(const Number &other) const { return val != other.val; }

    Number inv() const {
        return Number(inverse(val));
    }

    Number pow(long long p) const {
        assert(p >= 0);
        Number base = *this, result = 1;
        while (p > 0) {
            if (p & 1)
                result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

