        }

    map<vector<bool>, Number> state_map;
    vector<bool> init_mask(1 << N, false);
    init_mask[0] = true;
    state_map[init_mask] = 1;
    vector<bool> temp_mask;

    for (int left_idx = 0; left_idx < N; left_idx++) {
        map<vector<bool>, Number> new_state_map;
        for (int mask_curr = 0; mask_curr < (1 << N); mask_curr++) {
            Number product = 1;
            for (int right_idx = 0; right_idx < N; right_idx++)
                product *= (mask_curr >> right_idx & 1) ? prob[left_idx][right_idx] : Number(1) - prob[left_idx][right_idx];

            for (auto &entry : state_map) {
                const vector<bool> &possible_mask = entry.first;
                Number prob_value = entry.second;
                temp_mask.assign(1 << N, false);
                for (int m = 0; m < (1 << N); m++)
                    if (possible_mask[m])
                        for (int i = 0; i < N; i++)
                            if ((mask_curr >> i & 1) != 0 && (m >> i & 1) == 0)
                                temp_mask[m | (1 << i)] = true;

                new_state_map[temp_mask] += prob_value * product;
            }
        }
        state_map = new_state_map;
    }

    Number total = 0;
    for (auto &p : state_map)
        if (p.first[(1 << N) - 1])
            total += p.second;

    cout << (int) total << '\n';
