import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class Number {
        int val;

        Number(long v) {
            v %= MOD;
            if (v < 0) v += MOD;
            val = (int) v;
        }

        static int inverse(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int temp = g % r;
                g = r;
                r = temp;
                int x1 = x - q * y;
                x = y;
                y = x1;
            }
            return x < 0 ? x + m : x;
        }

        static int inverse(int a) {
            return inverse(a, MOD);
        }

        Number add(Number other) {
            int res = val + other.val;
            if (res >= MOD) res -= MOD;
            return new Number(res);
        }

        Number subtract(Number other) {
            int res = val - other.val;
            if (res < 0) res += MOD;
            return new Number(res);
        }

        static int fast_mod(long x, int m) {
            return (int) (x % m);
        }

        Number multiply(Number other) {
            long res = (long) val * other.val;
            res = fast_mod(res, MOD);
            return new Number(res);
        }

        Number divide(Number other) {
            return this.multiply(new Number(inverse(other.val)));
        }

        Number increment() {
            int newVal = val == MOD - 1 ? 0 : val + 1;
            return new Number(newVal);
        }

        Number decrement() {
            int newVal = val == 0 ? MOD - 1 : val - 1;
            return new Number(newVal);
        }

        Number negate() {
            return val == 0 ? new Number(0) : new Number(MOD - val);
        }

        Number inv() {
            return new Number(inverse(val));
        }

        Number pow(long p) {
            assert p >= 0;
            Number base = this;
            Number result = new Number(1);
            while (p > 0) {
                if ((p & 1) == 1) {
                    result = result.multiply(base);
                }
                base = base.multiply(base);
                p >>= 1;
            }
            return result;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Number)) return false;
            Number other = (Number) obj;
            return val == other.val;
        }

        @Override
        public int hashCode() {
            return Integer.hashCode(val);
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        Number[][] prob = new Number[N][N];

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(st.nextToken());
                prob[i][j] = new Number(p).divide(new Number(100));
            }
        }

        Map<List<Boolean>, Number> stateMap = new HashMap<>();
        List<Boolean> initMask = new ArrayList<>(Collections.nCopies(1 << N, false));
        initMask.set(0, true);
        stateMap.put(initMask, new Number(1));

        for (int leftIdx = 0; leftIdx < N; leftIdx++) {
            Map<List<Boolean>, Number> newStateMap = new HashMap<>();
            for (int maskCurr = 0; maskCurr < (1 << N); maskCurr++) {
                Number product = new Number(1);
                for (int rightIdx = 0; rightIdx < N; rightIdx++) {
                    boolean bitSet = ((maskCurr >> rightIdx) & 1) != 0;
                    if (bitSet) {
                        product = product.multiply(prob[leftIdx][rightIdx]);
                    } else {
                        product = product.multiply(new Number(1).subtract(prob[leftIdx][rightIdx]));
                    }
                }
                for (Map.Entry<List<Boolean>, Number> entry : stateMap.entrySet()) {
                    List<Boolean> possibleMask = entry.getKey();
                    Number probValue = entry.getValue();
                    List<Boolean> tempMask = new ArrayList<>(Collections.nCopies(1 << N, false));
                    for (int m = 0; m < (1 << N); m++) {
                        if (possibleMask.get(m)) {
                            for (int i = 0; i < N; i++) {
                                boolean maskBit = ((maskCurr >> i) & 1) != 0;
                                boolean mBit = ((m >> i) & 1) != 0;
                                if (maskBit && !mBit) {
                                    int newMaskVal = m | (1 << i);
                                    tempMask.set(newMaskVal, true);
                                }
                            }
                        }
                    }
                    Number prevProb = newStateMap.getOrDefault(tempMask, new Number(0));
                    newStateMap.put(tempMask, prevProb.add(probValue.multiply(product)));
                }
            }
            stateMap = newStateMap;
        }

        Number total = new Number(0);
        int fullMaskIndex = (1 << N) - 1;
        for (Map.Entry<List<Boolean>, Number> p : stateMap.entrySet()) {
            List<Boolean> mask = p.getKey();
            if (mask.get(fullMaskIndex)) {
                total = total.add(p.getValue());
            }
        }

        System.out.println((int) total.val);
    }
}
